package com.opensocket.aievent.core.iam.api.response;
import com.opensocket.aievent.core.iam.rbac.domain.shadow.ShadowRetentionRun;import java.time.Instant;
public record ShadowRetentionRunResponse(String runId,String status,long metricsDeleted,long receiptsDeleted,long deadLettersDeleted,int partitionsArchived,int partitionsPurged,String detailsJson,Instant startedAt,Instant completedAt,String actorId,String auditReason,String correlationId){public static ShadowRetentionRunResponse from(ShadowRetentionRun v){return new ShadowRetentionRunResponse(v.runId(),v.status(),v.metricsDeleted(),v.receiptsDeleted(),v.deadLettersDeleted(),v.partitionsArchived(),v.partitionsPurged(),v.detailsJson(),v.startedAt(),v.completedAt().orElse(null),v.actorId(),v.auditReason(),v.correlationId().orElse(null));}}
